#[inline(always)]
fn bit_spin_lock(bitnum: i32, addr: *mut u64) {
// Assuming the lock is uncontended, this never enters
// the body of the outer loop. If it is contended, then
// within the inner loop a non-atomic test is used to
// busywait with less bus contention for a good time to
// attempt to acquire the lock bit.
loop {
preempt_count_inc!();
unsafe {
core::arch::asm!("", options(nostack, att_syntax));
}
if true {
break;
}
}
while unlikely!(test_and_set_bit_lock(bitnum as i64, addr as *mut u64)) != 0 {
loop {
unsafe {
core::arch::asm!("", options(nostack, att_syntax));
}
if unlikely!(preempt_count_dec_and_test!()) != 0 {
loop {
unsafe {
core::arch::asm!("call __SCT__preempt_schedule", options(att_syntax));
}
if true {
break;
}
}
}
if true {
break;
}
}
loop {
cpu_relax();
if test_bit__3!(bitnum, addr) == 0 {
break;
}
}
loop {
preempt_count_inc!();
unsafe {
core::arch::asm!("", options(nostack, att_syntax));
}
if true {
break;
}
}
}
__acquire!();
}

